def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        marks = [i for i, value in enumerate(row) if value != 0]
        if len(marks) >= 2:
            for c in range(marks[0] + 1, marks[-1]):
                if row[c] == 0:
                    row[c] = 2
    return out
